import {createJourneys} from './journeys.mjs';
import {createLumoClient} from './shared-client.mjs';
import {encodeSharedQr,parseSharedQr,renderQr,mountScanner,decodeQrImage} from './qr.mjs';
import {createScopeGate} from './scope.mjs';
import {cash,esc,parseMoney,nextAmount,validateAccount,validateQuote,remainingRefund,receiptLabel,safeError} from './model.mjs';

const root=document.querySelector('#app');
const channel=document.body.dataset.channel==='merchant'?'merchant':'consumer';
const SESSION_KEY='lumo.connected.session.v1';
const state={page:'home',auth:'login',account:null,activity:[],merchants:[],selection:null,busy:false,error:'',pending:null,lastSync:0,recipient:null,review:null,receipt:null,receiptTitle:'',collectAmount:'',collectNote:'',collectMode:'amount',qr:null,scanError:'',fundAmount:10000,hideBalance:true,metadataAttempts:{},sound:false,soundFault:false,knownPayments:null,latestPayment:null};
const scopes=createScopeGate();
let lastAuthOwner=null,authChanging=false,storageSerial=0,renderedPage=null,replayingHistory=false;
let client,config,toastTimer,cameraAbort,cameraStop,polling=false,lastPoll=0,booted=false;
const paths={eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',eyeoff:'<path d="m3 3 18 18M10 5h2c6 0 10 7 10 7a24 24 0 0 1-4 4M6 6a24 24 0 0 0-4 6s4 7 10 7a14 14 0 0 0 6-2M10 10a3 3 0 0 0 4 4"/>',home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1z"/>',pay:'<path d="M4 12h16M14 6l6 6-6 6"/>',back:'<path d="m14 6-6 6 6 6M8 12h12"/>',scan:'<path d="M8 3H4a1 1 0 0 0-1 1v4M16 3h4a1 1 0 0 1 1 1v4M3 16v4a1 1 0 0 0 1 1h4M16 21h4a1 1 0 0 0 1-1v-4M7 7h3v3H7zM14 7h3v3h-3zM7 14h3v3H7zM14 14h3v3h-3z"/>',activity:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',add:'<path d="M12 4v16M4 12h16"/>',receive:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 7M20 3v5h-5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m4 12 5 5L20 6"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',shop:'<path d="M3 9h18l-2-6H5zM4 10v11h16V10M8 21v-7h5v7M3 9v2a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0V9"/>',settings:'<path d="m10 2-1 3-3 1-3 4 2 2-1 3 3 4 3-1 2 3 4-1 1-3 3-1 1-5-3-1-1-3-4-2z"/><circle cx="12" cy="12" r="3"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',logout:'<path d="M9 4H4v16h5M8 12h13m-5-5 5 5-5 5"/>',sound:'<path d="m4 9 4 0 5-5v16l-5-5H4zM17 8a6 6 0 0 1 0 8M20 5a10 10 0 0 1 0 14"/>',mute:'<path d="m3 9 4 0 5-5v16l-5-5H3zM17 9l5 6m0-6-5 6"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',arrowin:'<path d="M18 6 6 18M6 6v12h12"/>',arrowout:'<path d="M6 18 18 6M6 6h12v12"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3z"/><circle cx="12" cy="13" r="4"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const icon=(name,size=22)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.pay}</svg>`;
const button=(text,action,{secondary=false,ghost=false,disabled=false,extra=''}={})=>`<button class="button${secondary?' secondary':''}${ghost?' ghost':''}" data-action="${action}"${disabled?' disabled':''} ${extra}>${text}</button>`;
const back=(target='home',label=channel==='merchant'?'Home':'Back')=>`<button class="back" data-page="${target}">${icon('back',18)}${label}</button>`;
const field=(name,label,{type='text',placeholder='',max='',autocomplete='',value='',required=true,pattern='',inputmode=''}={})=>`<label class="field">${label}<input name="${name}" type="${type}" ${required?'required':''}${max?` maxlength="${max}"`:''}${pattern?` pattern="${pattern}"`:''}${inputmode?` inputmode="${inputmode}"`:''}${autocomplete?` autocomplete="${autocomplete}"`:''} placeholder="${esc(placeholder)}" value="${esc(value)}"></label>`;
const ticket=()=>scopes.capture(client?.user?.id||null);
const assertTicket=t=>scopes.assert(t,client?.user?.id||null);
function clearAccountView(){try{window.speechSynthesis?.cancel();}catch{}renderedPage=null;journeys.reset();scopes.invalidate();stopCamera();Object.assign(state,{account:null,activity:[],merchants:[],selection:null,pending:null,recipient:null,review:null,receipt:null,qr:null,knownPayments:null,latestPayment:null,soundFault:false,page:'home',collectAmount:'',collectNote:'',collectMode:'amount',receiptTitle:'',error:'',scanError:'',lastSync:0,fundAmount:10000,metadataAttempts:{}});}
const moneyBlocked=()=>state.busy||!!state.pending;
const selected=()=>{for(const merchant of state.merchants){const shop=merchant.shops?.find(s=>s.id===state.selection);if(shop)return {merchant,shop};}const merchant=state.merchants[0],shop=merchant?.shops?.[0];return {merchant,shop};};
const currentActivity=()=>channel==='merchant'?(selected().merchant?.activity||[]):state.activity;
const merchantRole=()=>selected().shop?.role||selected().merchant?.role||'owner';
const receivingStatus=()=>!navigator.onLine||Date.now()-state.lastSync>20000?'Connection lost':!state.sound?'Muted':!('speechSynthesis'in window)?'Sound unavailable':state.soundFault?'Sound failed':'Ready';
const journeys=createJourneys({state,getClient:()=>client,channel,root,go,render:()=>renderPreservingForms(),action,refresh,completeMoney,ticket,assertTicket,toast,selected,moneyBlocked});

function toast(message){clearTimeout(toastTimer);const node=document.querySelector('#toast');node.textContent=message;node.classList.add('visible');toastTimer=setTimeout(()=>node.classList.remove('visible'),4500);}
function stopCamera(){cameraAbort?.abort();cameraAbort=null;cameraStop?.();cameraStop=null;}
function setBusy(value){state.busy=value;root.setAttribute('aria-busy',String(value));root.querySelectorAll('button,input,select,textarea').forEach(el=>{if(value){el.dataset.wasDisabled=String(el.disabled);el.disabled=true;}else{el.disabled=el.dataset.wasDisabled==='true';delete el.dataset.wasDisabled;}});root.querySelector('.loading-line')?.remove();if(value)root.insertAdjacentHTML('afterbegin','<div class="loading-line" aria-hidden="true"></div>');}
function showError(error){state.error=safeError(error);const target=document.querySelector('#inline-error');if(target)target.textContent=state.error;else toast(state.error);}
const authDenied=error=>['AUTH_REQUIRED','SIGN_IN_REQUIRED','SESSION_REVOKED'].includes(error?.code);
async function expireSession(){clearAccountView();await client.signOut().catch(()=>{});if(!client.signedIn){state.error='Sign in again to open your shared account.';render();}}
async function pending(){if(!client?.signedIn){state.pending=null;return;}const scope=ticket(),value=await client.getPending();assertTicket(scope);state.pending=value;}
async function action(work,{renderAfter=true}={}){if(state.busy)return;const scope=ticket();let failed=false;state.error='';document.querySelector('#inline-error')?.replaceChildren();setBusy(true);try{await work();}catch(error){failed=true;if(!scopes.valid(scope,client?.user?.id||null))return;if(authDenied(error)){await expireSession();return;}showError(error);try{await pending();}catch{}if(state.pending){state.page='pending';renderAfter=true;}}finally{setBusy(false);if(renderAfter){if(failed)renderPreservingForms();else render();}}}
function go(page){stopCamera();state.error='';state.scanError='';state.page=page;render();document.querySelector('main')?.focus({preventScroll:true});}
function errorLine(){return `<p id="inline-error" class="error" role="alert">${esc(state.error)}</p>`;}
function header(){return `<header class="topbar"><a class="wordmark" href="${channel==='merchant'?'/merchant.html':'/'}" aria-label="Lumo ${channel==='merchant'?'Merchant':'Home'}">lumo${channel==='merchant'?'<span>merchant</span>':''}</a><div class="top-right"><span class="badge">Test money</span>${client?.signedIn?`<button class="icon-button refresh" data-action="refresh" aria-label="Refresh balances">${icon('refresh',19)}</button><button class="avatar" data-page="profile" aria-label="Your account">${esc((state.account?.displayName||'L').trim().slice(0,1).toUpperCase())}${journeys.ext.notifications.some(n=>!n.readAt&&!n.read)?'<span class="avatar-dot" aria-label="Unread updates"></span>':''}</button>`:''}</div></header>`;}
function nav(){const items=channel==='merchant'?[['home','Home','home'],['collect','Collect','scan'],['admin','Administration','settings']]:[['home','Home','home'],['pay','Pay','pay'],['plan','Plan','activity'],['groups','Groups','person']];return `<nav class="bottom-nav" aria-label="Main navigation">${items.map(([page,label,i])=>`<button data-page="${page}" class="${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${icon(i,22)}<span>${label}</span></button>`).join('')}</nav>`;}
function pendingNotice(){return state.pending?`<aside class="notice pending"><strong>${icon('clock',15)} Your original request is saved</strong>${Number.isSafeInteger(state.pending.payload.amount)?cash(state.pending.payload.amount)+' · ':''} ${esc(state.pending.command==='wallet.fund'?'test funding':state.pending.command==='payment.refund'?'merchant refund':'payment')}<p>Check its result before starting another money move.</p>${button('Check original request','pending',{ghost:true,disabled:state.busy})}</aside>`:'';}
function activityRows(rows,accountId,{limit=100}={}){if(!rows.length)return '<p class="empty">Your confirmed payments will appear here.</p>';return `<div class="activity">${rows.slice(0,limit).map(r=>{const incoming=r.payeeAccountId===accountId;return `<button class="activity-row" data-receipt="${esc(r.id)}"><span class="activity-icon">${icon(r.type==='merchant_payment'?'shop':incoming?'arrowin':'arrowout',20)}</span><span class="activity-copy"><strong>${esc(receiptLabel(r,accountId))}</strong><small>${date(r.createdAt)}</small></span><span class="activity-value ${incoming?'in':''}">${incoming?'+':'−'}${cash(r.amount)}</span></button>`;}).join('')}</div>`;}
function date(value){const d=new Date(value);return Number.isFinite(d.getTime())?esc(d.toLocaleDateString('en-GH',{day:'numeric',month:'short'})+' · '+d.toLocaleTimeString('en-GH',{hour:'2-digit',minute:'2-digit'})):'Confirmed';}
function syncLine(){return `<div class="sync-line">${state.lastSync?'Synced '+new Date(state.lastSync).toLocaleTimeString('en-GH',{hour:'2-digit',minute:'2-digit'}):'Checking your account…'}</div>`;}
function authView(){const register=state.auth==='register';return `<main class="auth-page" tabindex="-1"><div class="auth-hero"><h1>${channel==='merchant'?'Your shop.<br>Ready to collect.':'Money,<br>clearer.'}</h1><p>${channel==='merchant'?'Get paid with a QR. Keep every shop in view.':'Pay your people. Pay your campus. Keep your money in view.'}</p></div><div class="auth-tabs"><button data-auth="login" class="${!register?'active':''}">Sign in</button><button data-auth="register" class="${register?'active':''}">Create account</button></div><form id="auth-form" novalidate>${register?field('displayName','What should we call you?',{max:80,autocomplete:'name',placeholder:'Your name'}):''}${field('handle','Your Lumo handle',{max:30,autocomplete:'username',placeholder:'e.g. william',pattern:'[a-z][a-z0-9_]{2,29}'})}${field('password','Password',{type:'password',max:72,autocomplete:register?'new-password':'current-password',placeholder:register?'At least 8 characters':'Your password'})}${register?`${field('pin','Choose your payment PIN',{type:'password',inputmode:'numeric',max:6,autocomplete:'new-password',placeholder:'4–6 digits',pattern:'[0-9]{4,6}'})}${field('confirmPin','Confirm your payment PIN',{type:'password',inputmode:'numeric',max:6,autocomplete:'new-password',placeholder:'Enter the same PIN again',pattern:'[0-9]{4,6}'})}<label class="check"><input name="consent" type="checkbox" required><span>I understand this pilot uses test money. My handle identifies my account; it does not verify my phone or identity.</span></label>`:''}${errorLine()}<button class="button" type="submit">${register?'Create my Lumo account':'Sign in'}${icon('pay',18)}</button></form><p class="auth-note">${channel==='merchant'?'Use the same Lumo account as the consumer app. ':''}Test funds have no real monetary value.</p><div class="page-footer"><a class="subtle-link" href="${channel==='merchant'?'/':'/merchant.html'}">${icon(channel==='merchant'?'person':'shop',17)}${channel==='merchant'?'Open consumer Lumo':'Open Lumo Merchant'}</a></div></main>`;}
function consumerHome(){const a=state.account,p=journeys.ext.plan,primary=p?.revision?Math.max(0,p.leftAfterPlan):a.balance,label=p?.revision?'Left after plan':'Available now';return `<main class="consumer-home" tabindex="-1"><p class="greeting">${esc(a.displayName.split(' ')[0])}, your money is here.</p>${pendingNotice()}<section class="balance-card"><div class="balance-label"><span>${label}</span><button class="icon-button" data-action="toggle-balance" aria-label="${state.hideBalance?'Show':'Hide'} balances">${icon(state.hideBalance?'eyeoff':'eye',18)}</button></div><div class="balance" aria-label="${state.hideBalance?'Balance hidden':cash(primary)}">${state.hideBalance?'••••':cash(primary)}</div><p class="handle">${p?.revision?'Everyday '+(state.hideBalance?'••••':cash(a.balance)):'@'+esc(a.handle)}</p></section><div class="home-actions">${button(icon('add',19)+'Add test funds','fund',{secondary:true,disabled:moneyBlocked()})}${button('Pay'+icon('pay',19),'pay',{disabled:moneyBlocked()})}</div><div class="quick-grid"><button class="quick-tile" data-page="scan">${icon('scan',24)}<span>Scan to pay</span></button><button class="quick-tile" data-action="myqr">${icon('receive',24)}<span>Receive money</span></button></div><div class="section-head"><h2>Latest activity</h2><button data-page="activity">View all</button></div>${activityRows(state.activity,a.id,{limit:3})}${syncLine()}</main>`;}
function payView(){return `<main tabindex="-1">${back()}<h1 class="page-title">Pay someone.</h1>${pendingNotice()}<p class="pay-intro">A Lumo handle is all you need. You’ll check who receives it before paying.</p><form id="recipient-form">${field('handle','Their Lumo handle',{placeholder:'e.g. akua',max:30,autocomplete:'off'})}${errorLine()}<button class="button" type="submit" ${moneyBlocked()?'disabled':''}>Find person${icon('pay',18)}</button></form><div class="gap"></div>${button(icon('scan',20)+'Scan a Lumo QR','scan',{secondary:true})}<div class="pay-extras"><button class="menu-row" data-jpage="discover"><span class="menu-copy"><strong>Campus Pay</strong><small>Find a published shop or pay by merchant code</small></span>›</button><button class="menu-row" data-jpage="favourites"><span class="menu-copy"><strong>Your people</strong><small>Saved Lumo recipients</small></span>›</button><button class="menu-row" data-jpage="requests"><span class="menu-copy"><strong>Request money</strong><small>Send, pay or decline a fixed request</small></span>›</button><button class="menu-row" data-jpage="schedules"><span class="menu-copy"><strong>Scheduled transfers</strong><small>Authorise and manage internal Lumo mandates</small></span>›</button></div><p class="notice">Bank transfers, MoMo, bills and top-ups need an external provider. They are not connected in this test-money build.</p><div class="page-footer">Transfers use your shared Everyday balance.</div></main>`;}
function amountView(){const r=state.recipient;return `<main tabindex="-1">${back('pay')}<h1 class="page-title">How much?</h1><div class="recipient-card"><span class="recipient-avatar">${esc(r.displayName.slice(0,1).toUpperCase())}</span><div><h2>${esc(r.displayName)}</h2><p>@${esc(r.handle)}</p></div></div><form id="amount-form"><label class="field amount-field-wrap"><span>Amount to send · GH₵</span><input class="amount-field" name="amount" inputmode="decimal" autocomplete="off" placeholder="0.00" maxlength="8" required></label><p class="small muted">${cash(state.account.balance)} available in Everyday</p><div class="gap"></div>${errorLine()}<button class="button" type="submit" ${moneyBlocked()?'disabled':''}>Review payment${icon('pay',18)}</button></form></main>`;}
function merchantPayView(){const r=state.review,q=r.quote,fixed=!!r.intent.requestId;return `<main tabindex="-1">${back('scan')}<h1 class="page-title">Pay merchant</h1><div class="recipient-card"><span class="recipient-avatar">${icon('shop',24)}</span><div><h2>${esc(q.merchant.name)}</h2><p>${esc(q.shop.name)}</p></div></div><form id="merchant-amount-form">${fixed?`<div class="money-review"><span class="locked">${icon('lock',13)}Amount locked by merchant</span><div class="review-amount">${cash(q.request.amount)}</div>${q.request.note?`<p class="muted small">${esc(q.request.note)}</p>`:''}</div>`:`<label class="field amount-field-wrap"><span>Amount to pay · GH₵</span><input class="amount-field" name="amount" inputmode="decimal" autocomplete="off" placeholder="0.00" maxlength="8" required></label>`}<div class="detail"><span>Paying from</span><strong>Everyday · ${cash(state.account.balance)}</strong></div>${errorLine()}<div class="gap"></div><button class="button" type="submit" ${moneyBlocked()?'disabled':''}>Review payment${icon('pay',18)}</button></form></main>`;}
function reviewView(){const r=state.review,draft={command:r.kind==='merchant'?'payment.pay':'transfer',amount:r.amount,budgetCategoryId:r.budgetCategoryId||''},ready=r.kind==='refund'||journeys.outflowReady(draft),name=r.kind==='transfer'?r.recipient.displayName:r.kind==='refund'?'Original customer':r.quote.merchant.name;return `<main tabindex="-1">${back(r.kind==='transfer'?'amount':r.kind==='refund'?'activity':'merchant-pay')}<h1 class="page-title">${r.kind==='refund'?'Review refund':'Check your payment.'}</h1><div class="money-review"><p class="muted small">${r.kind==='refund'?'Returning to':'Paying'}</p><h2>${esc(name)}</h2>${r.kind==='transfer'?`<p class="muted small">@${esc(r.recipient.handle)}</p>`:r.kind==='merchant'?`<p class="muted small">${esc(r.quote.shop.name)}</p>`:''}<div class="review-amount">${cash(r.amount)}</div>${r.kind==='merchant'&&r.intent.requestId?`<span class="locked">${icon('lock',13)}Amount locked by merchant</span>`:''}</div><div class="details"><div class="detail"><span>${r.kind==='refund'?'Returning from':'Paying from'}</span><strong>${r.kind==='refund'?esc(selected().merchant?.name):'Everyday'}</strong></div><div class="detail"><span>Fee</span><strong>${cash(0)}</strong></div>${r.kind==='refund'?`<div class="detail"><span>Original receipt</span><strong>${esc(r.payment.reference)}</strong></div>`:''}</div><form id="approve-form">${r.kind!=='refund'?journeys.sourcePicker(r.budgetCategoryId||''):''}${ready?field('pin','Enter your payment PIN',{type:'password',inputmode:'numeric',max:6,autocomplete:'off',placeholder:'4–6 digits',pattern:'[0-9]{4,6}'}):''}${errorLine()}<button class="button" type="submit" ${moneyBlocked()?'disabled':''}>${!ready?'See payment impact':r.kind==='refund'?'Confirm refund':'Pay '+cash(r.amount)}${icon('pay',18)}</button></form><p class="page-footer">This is a shared test-money payment.</p></main>`;}
function activityView(){const activity=currentActivity(),account=channel==='merchant'?selected().merchant?.accountId:state.account?.id;return `<main tabindex="-1"><div class="inline-head"><h1>Activity</h1><button class="icon-button" data-action="refresh" aria-label="Refresh activity">${icon('refresh',19)}</button></div>${pendingNotice()}${activityRows(activity,account)}${syncLine()}</main>`;}
function receiptView(){const r=state.receipt,incoming=r.payeeAccountId===(channel==='merchant'?selected().merchant?.accountId:state.account.id);const canRefund=channel==='merchant'&&merchantRole()!=='cashier'&&r.type==='merchant_payment'&&r.payeeAccountId===selected().merchant?.accountId&&remainingRefund(r,currentActivity())>0;return `<main tabindex="-1">${back('activity')}<h1 class="page-title">Receipt</h1><div class="money-review"><span class="locked">${icon('check',14)}Confirmed</span><div class="review-amount">${incoming?'+':'−'}${cash(r.amount)}</div><p>${esc(receiptLabel(r,channel==='merchant'?selected().merchant?.accountId:state.account.id))}</p></div><div class="details"><div class="detail"><span>Status</span><strong>Posted</strong></div><div class="detail"><span>Date</span><strong>${date(r.createdAt)}</strong></div>${r.payerHandle?`<div class="detail"><span>From</span><strong>@${esc(r.payerHandle)}</strong></div>`:''}${r.payeeHandle?`<div class="detail"><span>To</span><strong>@${esc(r.payeeHandle)}</strong></div>`:''}<div class="detail"><span>Reference</span><strong>${esc(r.reference)}</strong></div></div>${button(icon('copy',18)+'Copy receipt reference','copy-reference',{ghost:true})}${canRefund?button('Refund original customer','refund',{secondary:true,disabled:moneyBlocked()}):''}<p class="page-footer">The other account has the same receipt reference.<br>Test money · no real funds moved.</p></main>`;}
function successView(){const r=state.receipt;return `<main class="success-page" tabindex="-1"><div class="success-check">${icon('check',38)}</div><h1>${esc(state.receiptTitle||'Payment complete.')}</h1><div class="balance">${cash(r.amount)}</div><p>${r.type==='refund'?'Returned to the original customer’s Lumo account.':r.type==='test_funding'?'Your test funds are ready in Everyday.':'Confirmed in both accounts.'}</p><div class="reference"><small>Receipt reference</small>${esc(r.reference)}</div><button class="text-button" data-action="copy-reference">${icon('copy',16)} Copy reference</button>${r.type!=='refund'?`<div class="details"><div class="detail"><span>Everyday balance</span><strong>${cash(state.account.balance)}</strong></div></div>`:''}${button('Done','done')}<p class="page-footer">Test money · no real funds moved.</p></main>`;}
function profileView(){const a=state.account;return `<main tabindex="-1"><div class="profile-card"><span class="recipient-avatar">${esc(a.displayName.slice(0,1).toUpperCase())}</span><div><h1>${esc(a.displayName)}</h1><p>@${esc(a.handle)}</p></div></div>${pendingNotice()}<div class="notice"><strong>Connected Lumo pilot</strong>One shared account across the consumer and merchant apps. Balances contain test funds.</div>${menuRow('scan','My Lumo QR','Let another person send to your handle.','myqr')}${menuRow('add','Add test funds','Practice payments with no real money.','fund')}${menuRow('shop',channel==='merchant'?'Consumer Lumo':'Lumo Merchant',channel==='merchant'?'Send, pay and receive in your personal account.':'Collect payments for your business.','switch-channel')}${journeys.profileRows()}${menuRow('logout','Sign out','Your balances and receipts stay in Lumo.','signout')}<p class="page-footer">This pilot does not verify your phone or identity.<br>Keep your password and payment PIN private.</p></main>`;}
function menuRow(i,title,description,action){return `<button class="menu-row" data-action="${action}">${icon(i,21)}<span class="menu-copy"><strong>${esc(title)}</strong>${description?`<small>${esc(description)}</small>`:''}</span>${icon('chevron',17)}</button>`;}
function fundView(){return `<main tabindex="-1">${back()}<h1 class="page-title">Add test funds</h1>${pendingNotice()}<p class="fund-info">Choose an amount to try transfers and merchant payments. These funds have no real monetary value.</p><div class="fund-options">${[5000,10000,50000,100000].map(a=>`<button data-fund="${a}" class="${state.fundAmount===a?'active':''}">${cash(a)}</button>`).join('')}</div><form id="fund-form"><label class="check"><input name="confirm" type="checkbox" required><span>I understand that this adds test funds, with no real money moved.</span></label>${errorLine()}<button type="submit" class="button" ${moneyBlocked()?'disabled':''}>Add ${cash(state.fundAmount)}</button></form></main>`;}
const pinCommands=new Set(['transfer','payment.pay','payment.refund','group.contribute','group.payout.request','group.payout.approve','group.cancel','box.save','box.withdraw','box.partner.respond','box.release.decide','iou.pay','refund.decide','person.request.pay','schedule.create','schedule.cancel','security.session.revoke']);
function pendingView(){const p=state.pending;if(!p)return `<main tabindex="-1">${back()}<h1 class="page-title">No saved request</h1><p class="muted">Your last confirmed payment is in Activity.</p></main>`;return `<main tabindex="-1">${back()}<h1 class="page-title">Check the original.</h1><div class="money-review"><span class="locked">${icon('clock',14)}Result being checked</span><div class="review-amount">${Number.isSafeInteger(p.payload.amount)?cash(p.payload.amount):esc(p.command)}</div></div><p class="muted small">The original details and reference are saved. A fresh payment is blocked until this result is confirmed.</p><div class="reference"><small>Saved reference</small>${esc(p.payload.attemptId)}</div>${button('Check saved result','recover',{disabled:state.busy})}<div class="gap"></div><form id="retry-form">${pinCommands.has(p.command)?field('pin','Re-enter your PIN to retry the same request',{type:'password',inputmode:'numeric',max:6,autocomplete:'off',placeholder:'4–6 digits',pattern:'[0-9]{4,6}'}):''}${['box.create','box.withdraw'].includes(p.command)&&p.payload.partnerInvitationId||p.command==='box.withdraw'&&p.payload.releaseId?field('partnerCode','Re-enter the private partner approval code',{type:'password',max:100,autocomplete:'off'}):''}${p.command==='security.pin'?field('oldPin','Current payment PIN',{type:'password',max:6,autocomplete:'off'})+field('newPin','The new payment PIN from your original request',{type:'password',max:6,autocomplete:'off'}):''}${errorLine()}<button class="button ghost" type="submit" ${state.busy?'disabled':''}>Retry original ${p.command==='wallet.fund'?'test funding':'request'}</button></form></main>`;}
function qrView(){const q=state.qr,expired=!!(q.request&&!q.received&&Date.parse(q.request.expiresAt)<=Date.now());const label=q.kind==='person'?`@${q.intent.handle}`:q.merchant.name;return `<main class="qr-show" tabindex="-1">${back(q.kind==='person'?'home':'collect')}<h1>${esc(q.received?'Payment received.':label)}</h1>${q.latestReceived?`<div class="incoming-confirmation" role="status" aria-live="polite"><strong>${cash(q.latestReceived.amount)} received</strong><span>@${esc(q.latestReceived.payerHandle||'customer')} · ${esc(q.latestReceived.reference)}</span></div>`:''}${q.kind==='merchant'?`<p>${esc(q.shop.name)}</p>${q.request?`<div class="qr-amount">${cash(q.request.amount)}</div><span class="locked">${icon('lock',13)}Exact amount</span>`:'<p>Customer enters the amount in Lumo.</p>'}`:'<p>Scan with Lumo to send money to your account.</p>'}<div class="qr-card">${renderQr(q.raw)}</div>${q.kind==='merchant'?`<div class="qr-state ${q.received?'paid':''}">${icon(q.received?'check':'clock',16)}${q.received?'Confirmed · '+esc(q.received.reference):expired?'This request has expired':q.request?'Waiting for this payment':'Ready to receive payments'}</div>`:''}${q.request?.note?`<p>${esc(q.request.note)}</p>`:''}${q.request?`<p class="small">Request expires ${new Date(q.request.expiresAt).toLocaleTimeString('en-GH',{hour:'2-digit',minute:'2-digit'})}</p>`:''}${button(icon('copy',17)+'Copy Lumo QR code','copy-qr',{ghost:true})}${q.kind==='merchant'&&q.request?button(q.received?'Collect another payment':'New amount','new-amount',{secondary:true}):''}<p class="page-footer">${q.kind==='merchant'?'The customer reviews and authorises in Lumo.':'Your balance updates when the sender confirms.'}</p></main>`;}
function scanView(){return `<main tabindex="-1">${back('pay')}<h1 class="page-title">Scan. Check. Pay.</h1><p class="muted small">Use a connected Lumo QR from a person or merchant.</p><div class="scanner"><video id="scan-video" playsinline muted></video><div id="scan-placeholder" class="scan-placeholder">${icon('scan',52)}</div><div class="scan-guide"></div></div><div class="camera-actions">${button(icon('camera',18)+'Enable camera','camera',{secondary:true})}${button(icon('image',18)+'QR photo','qr-photo',{ghost:true})}<input class="file-input" id="qr-file" type="file" accept="image/*"></div><p id="scan-error" class="error" role="alert">${esc(state.scanError)}</p><form id="qr-paste-form" class="scan-paste"><label class="field">Or paste a Lumo QR code<textarea name="code" rows="2" maxlength="2048" placeholder="lumo:shared:v1:…" required></textarea></label><button class="button ghost" type="submit">Read code${icon('pay',18)}</button></form></main>`;}
function shopSelector(){const count=state.merchants.reduce((n,m)=>n+(m.shops?.length||0),0);return `<label class="shop-select">${icon('shop',18)}<select id="shop-selector" aria-label="Receiving shop">${state.merchants.flatMap(m=>(m.shops||[]).map(s=>`<option value="${esc(s.id)}" ${s.id===selected().shop?.id?'selected':''}>${esc(count>1?m.name+' · '+s.name:s.name)}</option>`)).join('')}</select></label>`;}
function merchantSetup(){return `<main class="merchant-setup" tabindex="-1"><h1>Your business.<br>Ready for Lumo.</h1><p>Create your receiving shop. Your owner account will see its collections and balance.</p><form id="merchant-form">${field('businessName','Business name',{max:100,placeholder:'e.g. Akua’s Kitchen',autocomplete:'organization'})}${field('shopName','Shop name',{max:100,placeholder:'e.g. Night Market'})}${errorLine()}<button class="button" type="submit">Create receiving shop${icon('pay',18)}</button></form><p class="page-footer">Owner access · shared test-money pilot</p></main>`;}
function merchantHome(){const {merchant:m,shop:s}=selected();const payments=(m.activity||[]).filter(r=>r.shopId===s.id&&r.type==='merchant_payment'&&Date.parse(r.createdAt)>=Date.parse(s.tradingSince));return `<main tabindex="-1"><div class="shop-line"><span class="eyebrow">Your business</span>${shopSelector()}</div><h1 class="merchant-title">Let’s get you paid.</h1>${pendingNotice()}<div class="balance-card"><div class="balance-label"><span>Collected since last close</span>${icon('shop',17)}</div><div class="balance">${cash(s.netCollected)}</div><p class="handle">${esc(s.name)}</p><div class="merchant-metrics"><div class="merchant-metric"><small>${Number.isSafeInteger(s.confirmedCount)?'Confirmed payments':'Recent payments'}</small><strong>${Number.isSafeInteger(s.confirmedCount)?s.confirmedCount:payments.length}</strong></div>${Number.isSafeInteger(m.balance)?`<div class="merchant-metric"><small>Business balance</small><strong>${cash(m.balance)}</strong></div>`:''}</div></div><div class="merchant-toolbar"><button data-action="sound">${icon(state.sound?'sound':'mute',17)} Sound ${state.sound?'on':'off'}</button><span>${esc(merchantRole())} · ${esc(receivingStatus())}</span></div>${button('Collect a payment'+icon('pay',18),'collect',{disabled:state.busy})}<div class="section-head"><h2>Latest payments</h2><button data-page="activity">View all</button></div>${activityRows(m.activity||[],m.accountId,{limit:3})}${syncLine()}</main>`;}
function collectView(){const {merchant:m,shop:s}=selected(),staticRaw=encodeSharedQr({kind:'merchant',shopId:s.id});return `<main class="collect-page" tabindex="-1"><div class="collect-heading"><h1>Collect payment</h1>${shopSelector()}</div>${state.pending?pendingNotice():''}<section class="collect-terminal ${state.collectMode==='static'?'static-terminal':''}"><div class="collect-tabs" role="tablist" aria-label="Collection type"><button role="tab" data-collect="amount" aria-selected="${state.collectMode==='amount'}" class="${state.collectMode==='amount'?'active':''}">${icon('scan',17)}Enter amount</button><button role="tab" data-collect="static" aria-selected="${state.collectMode==='static'}" class="${state.collectMode==='static'?'active':''}">${icon('shop',18)}Shop QR</button></div>${state.collectMode==='static'?`${state.latestPayment?.shopId===s.id?`<div class="incoming-confirmation" role="status" aria-live="polite"><strong>${cash(state.latestPayment.amount)} received</strong><span>${esc(state.latestPayment.reference)}</span></div>`:''}<div class="static-identity"><h2>${esc(s.name)}</h2><p>${esc(m.name)}</p></div><div class="qr-card">${renderQr(staticRaw)}</div><p class="small">One QR for your shop. The customer enters the amount in Lumo.</p><div class="static-actions">${button('Show Shop QR','static-qr')}${button(icon('copy',16)+'Copy QR code','copy-static',{ghost:true})}</div>`:`<div class="collect-amount"><small>Amount to receive · GH₵</small><strong><span id="collect-value">${esc(state.collectAmount||'0.00')}</span><span class="amount-caret" aria-hidden="true"></span></strong></div><label class="collect-note"><span class="sr-only">Optional payment note</span><input id="collect-note" placeholder="Add a note (optional)" maxlength="160" value="${esc(state.collectNote)}" autocomplete="off"></label><div class="keypad" aria-label="Payment amount keypad">${['1','2','3','4','5','6','7','8','9','.','0','back'].map(k=>`<button data-key="${k}" aria-label="${k==='back'?'Delete last digit':k==='.'?'Decimal point':k}">${k==='back'?icon('back',23):k}</button>`).join('')}</div><button class="button collect-generate" data-action="generate" ${!parseMoney(state.collectAmount)||moneyBlocked()?'disabled':''}>Generate payment QR${icon('pay',18)}</button><div class="collect-foot">${icon('shield',14)}${esc(receivingStatus())} · Customer pays the exact amount</div>`}</section>${errorLine()}</main>`;}
function adminView(){const {merchant:m,shop:s}=selected();return `<main tabindex="-1"><h1 class="page-title">Administration</h1><div class="shop-line"><span class="small muted">Managing</span>${shopSelector()}</div>${pendingNotice()}<div class="admin-panel">${journeys.adminRows()}${menuRow('shop',m.name,s.name,'static-qr')}${menuRow('activity','Payments & refunds','View confirmed payments and return money to the original customer.','activity')}${merchantRole()!=='cashier'?menuRow('clock','Close this trading day','Reset this shop’s collection view while retaining business funds.','close-shop'):''}</div><div class="admin-section">Your ${esc(merchantRole())} account</div><div class="admin-panel">${menuRow('person',state.account.displayName,'@'+state.account.handle,'profile')}${merchantRole()==='owner'?menuRow('add','Add another shop','Collect separately within this business balance.','add-shop')+menuRow('add','Add another business','Create a separate receiving shop and balance.','add-business'):''}${menuRow(state.sound?'sound':'mute','Payment sound',state.sound?'Announce new payments while this page is open.':'Turn on spoken payment confirmations.','sound')}${menuRow('logout','Sign out','Your business records stay in Lumo.','signout')}</div><p class="page-footer">${esc(merchantRole())} access · connected test-money pilot</p></main>`;}
function shopSetupView(){const {merchant}=selected();return `<main tabindex="-1">${back('admin')}<h1 class="page-title">Add a shop</h1><p class="auth-subtitle">${esc(merchant.name)} · one business balance</p><form id="shop-form">${field('name','Shop name',{max:100,placeholder:'e.g. Legon Main Gate'})}${errorLine()}<button class="button" type="submit">Create receiving shop${icon('pay',18)}</button></form><p class="page-footer">Each shop has its own QR and collection counter.</p></main>`;}
function refundView(){const payment=state.receipt,max=remainingRefund(payment,currentActivity());return `<main tabindex="-1">${back('receipt')}<h1 class="page-title">Refund a customer</h1><div class="refund-original"><strong>${cash(payment.amount)} original payment</strong><p>${esc(payment.reference)}</p><p>Funds return to the account that paid.</p></div><form id="refund-form"><label class="field">Refund amount · GH₵<input name="amount" inputmode="decimal" value="${(max/100).toFixed(2)}" required maxlength="8"></label><p class="small muted">Up to ${cash(max)} available to refund.</p>${errorLine()}<div class="gap"></div><button class="button" type="submit" ${moneyBlocked()?'disabled':''}>Review refund${icon('pay',18)}</button></form></main>`;}

function renderPreservingForms(){
  const active=document.activeElement,focus=active&&root.contains(active)?{form:active.closest('form')?.id||active.closest('form')?.dataset.jform||'',name:active.name,start:active.selectionStart,end:active.selectionEnd}:null;
  const forms=Array.from(root.querySelectorAll('form')).map(f=>({key:f.id||f.dataset.jform,fields:Array.from(f.elements).filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type,disabled:e.disabled}))}));
  const expanded=Array.from(root.querySelectorAll('details')).map(d=>d.open),scroll=root.querySelector('main')?.scrollTop||0;
  render();
  for(const saved of forms){const form=Array.from(root.querySelectorAll('form')).find(f=>(f.id||f.dataset.jform)===saved.key);if(!form)continue;for(const item of saved.fields){const el=form.elements.namedItem(item.name);if(el){if(item.type!=='file')el.value=item.value;if(item.type==='checkbox'||item.type==='radio')el.checked=item.checked;el.disabled=item.disabled;}}}
  root.querySelectorAll('details').forEach((d,i)=>{if(expanded[i])d.open=true;});
  if(root.querySelector('main'))root.querySelector('main').scrollTop=scroll;
  if(focus?.name){const form=Array.from(root.querySelectorAll('form')).find(f=>(f.id||f.dataset.jform)===focus.form),el=form?.elements.namedItem(focus.name);if(el){el.focus({preventScroll:true});try{el.setSelectionRange(focus.start,focus.end);}catch{}}}
}
function render(){stopCamera();root.setAttribute('aria-busy',String(state.busy));if(!client){return;}if(authChanging){root.innerHTML=header()+'<main class="empty-error"><h1>Opening your account.</h1><p>Checking the signed-in Lumo account…</p></main>';return;}if(!client.signedIn){root.innerHTML=header()+authView();bind();return;}if(!state.account){root.innerHTML=header()+`<main class="empty-error" tabindex="-1"><h1>Opening your account.</h1><p>${esc(state.error||'Checking your shared balance and receipts…')}</p>${state.error?button('Try again','refresh')+button('Sign out','signout',{ghost:true}):''}</main>`;bind();return;}let content;const page=state.page;if(renderedPage!==page){const entry={lumoPage:page};if(replayingHistory){replayingHistory=false;}else if(renderedPage===null)history.replaceState(entry,'',location.href);else history.pushState(entry,'',location.href);renderedPage=page;}
  const extendedPage=journeys.page(page);if(extendedPage)content=extendedPage;else if(page==='refund'&&state.receipt)content=refundView();else if(page==='success')content=successView();else if(page==='receipt'&&state.receipt)content=receiptView();else if(page==='review'&&state.review)content=reviewView();else if(page==='pending')content=pendingView();else if(page==='qr'&&state.qr)content=qrView();else if(page==='scan')content=scanView();else if(page==='fund')content=fundView();else if(page==='profile')content=profileView();else if(page==='activity')content=activityView();else if(page==='merchant-pay'&&state.review)content=merchantPayView();else if(page==='amount'&&state.recipient)content=amountView();else if(page==='pay')content=payView();else if(channel==='merchant'&&page==='new-shop'&&state.merchants.length)content=shopSetupView();else if(channel==='merchant'&&(!state.merchants.length||page==='new-business'))content=merchantSetup();else if(channel==='merchant'&&page==='collect')content=collectView();else if(channel==='merchant'&&page==='admin')content=adminView();else content=channel==='merchant'?merchantHome():consumerHome();
  const rootPage=['home','pay','plan','groups','activity','profile','collect','admin'].includes(page);root.innerHTML=header()+content+(rootPage?nav():'');bind();if(state.busy)setBusy(true);
}

async function refresh({quiet=false}={}){
  if(!client.signedIn||polling||authChanging)return;
  polling=true;const scope=ticket(),owner=client.user.id;
  try{
    const [account,merchant]=await Promise.all([client.getAccount(),channel==='merchant'?client.getMerchant():Promise.resolve(null)]);
    assertTicket(scope);
    const accountView=validateAccount(account.account,owner),pendingView=await client.getPending();
    assertTicket(scope);
    // Commit the complete snapshot only after every await and identity check succeeds.
    state.account=accountView;state.activity=Array.isArray(account.activity)?account.activity:[];state.pending=pendingView;
    if(merchant){state.merchants=Array.isArray(merchant.merchants)?merchant.merchants:[];if(!state.merchants.some(m=>m.shops?.some(s=>s.id===state.selection)))state.selection=state.merchants[0]?.shops?.[0]?.id||null;handleNewMerchantPayments();}
    await journeys.sync({detail:['group','groups'].includes(state.page)});assertTicket(scope);state.lastSync=Date.now();state.error='';if(quiet){if(!['scan','pause'].includes(state.page))renderPreservingForms();}else render();
  }catch(error){if(scopes.valid(scope,client?.user?.id||null)){if(authDenied(error)){await expireSession();}else if(!quiet){showError(error);render();}}}
  finally{polling=false;if(!scopes.valid(scope,client?.user?.id||null)&&client.signedIn&&!state.account&&!authChanging)queueMicrotask(()=>refresh({quiet:false}));}
}
function handleNewMerchantPayments(){const {merchant:m,shop:s}=selected();const records=(m?.activity||[]).filter(r=>r.type==='merchant_payment'&&r.shopId===s?.id);const next=new Set(state.merchants.flatMap(m=>(m.activity||[]).map(r=>r.id)));const newest=records.find(r=>state.knownPayments&&!state.knownPayments.has(r.id));if(newest)state.latestPayment=newest;if(state.qr?.kind==='merchant'&&!state.qr.request&&newest)state.qr.latestReceived=newest;if(state.knownPayments&&state.sound&&!document.hidden){for(const r of records.filter(r=>!state.knownPayments.has(r.id)).reverse())speakPayment(r.amount);}state.knownPayments=next;if(state.qr?.kind==='merchant'&&state.qr.request){const received=records.find(r=>r.requestId===state.qr.request.id);if(received)state.qr.received=received;}}
function speak(text){try{if(!('speechSynthesis'in window))return;const owner=client?.user?.id;const message=new SpeechSynthesisUtterance(text);message.lang='en-GH';message.rate=.95;message.onerror=()=>{if(owner!==client?.user?.id)return;state.soundFault=true;toast('Payment sound failed. Read the confirmed receipt and tap Sound to retry.');renderPreservingForms();};message.onend=()=>{if(owner===client?.user?.id)state.soundFault=false;};window.speechSynthesis.speak(message);}catch{}}
function speakPayment(amount){speak(`Payment received. ${(amount/100).toFixed(2)} Ghana cedis.`);}
async function authRequest(kind,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const response=await fetch(config.supabaseUrl+'/functions/v1/lumo-pilot-auth/'+kind,{method:'POST',redirect:'error',signal:controller.signal,headers:{apikey:config.publishableKey,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(body)});let result;try{result=await response.json();}catch{throw new Error('Connection interrupted');}if(!response.ok||result.ok===false){const e=new Error('Account access failed');e.code=result.error?.code||result.code||'INVALID_CREDENTIALS';throw e;}return result.session||result;}finally{clearTimeout(timer);}}
async function signedIn(session){await client.restoreSession(session);const scope=ticket();await refresh();assertTicket(scope);const incoming=sessionStorage.getItem('lumo.connected.incoming.v1');if(incoming){sessionStorage.removeItem('lumo.connected.incoming.v1');try{await readQr(incoming);}catch(error){if(scopes.valid(scope,client?.user?.id||null))toast(safeError(error));}}}
async function readQr(raw){
  let intent;try{intent=parseSharedQr(raw.trim());}catch(error){state.scanError=error.message;const el=document.querySelector('#scan-error');if(el)el.textContent=state.scanError;else toast(state.scanError);return;}
  if(!client.signedIn){sessionStorage.setItem('lumo.connected.incoming.v1',raw);return;}
  const scope=ticket();stopCamera();
  if(intent.kind==='person'){const result=await client.lookupRecipient(intent.handle);assertTicket(scope);if(result.recipient.id===client.user.id){toast('That is your own Lumo account. Choose another person.');return;}state.recipient=result.recipient;state.review=null;go('amount');}
  else{const quote=validateQuote(intent,await client.quotePayment({shopId:intent.shopId,...(intent.requestId?{requestId:intent.requestId}:{})}));assertTicket(scope);state.review={kind:'merchant',intent,quote,amount:quote.request?.amount||null};go('merchant-pay');}
}
function showMyQr(){const intent={kind:'person',handle:state.account.handle};state.qr={kind:'person',intent,raw:encodeSharedQr(intent)};go('qr');}
function showStaticQr(){const {merchant,shop}=selected();if(!merchant||!shop)return;const intent={kind:'merchant',shopId:shop.id};state.qr={kind:'merchant',merchant,shop,intent,raw:encodeSharedQr(intent),openedAt:Date.now()};go('qr');}
async function copy(text,label){try{await navigator.clipboard.writeText(text);toast(label);}catch{toast('Copy is unavailable in this browser. You can scan the QR instead.');}}
async function completeMoney(result,title,scope=ticket()){assertTicket(scope);if(!result.receipt){await pending();assertTicket(scope);await refresh({quiet:true});assertTicket(scope);state.page='home';toast(result.refundProposal?'Refund sent to the owner for approval.':title||'Your request is confirmed.');return;}const account=validateAccount(result.account,client.user.id);const unresolved=await client.getPending();assertTicket(scope);state.account=account;state.receipt=result.receipt;state.receiptTitle=title;state.review=null;state.pending=unresolved;state.page='success';state.error='';await refresh({quiet:true});}
async function recover(){const scope=ticket(),result=await client.recoverPending();assertTicket(scope);await pending();assertTicket(scope);if(result.receipt)await completeMoney(result,result.receipt.type==='refund'?'Refund confirmed.':result.receipt.type==='test_funding'?'Test funds added.':'Payment confirmed.',scope);else if(result.ok===true&&result.attemptId){await completeMoney(result,'Your original request is confirmed.',scope);}else{toast('No result yet. Retry the same saved request below.');state.page='pending';}}
function updateCollect(key){state.collectAmount=nextAmount(state.collectAmount,key);const value=document.querySelector('#collect-value');if(value)value.textContent=state.collectAmount||'0.00';const generate=document.querySelector('[data-action="generate"]');if(generate)generate.disabled=!parseMoney(state.collectAmount)||moneyBlocked();}
function bind(){journeys.bind();root.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{go(el.dataset.page);if(['plan','groups','group','profile','activity','pay'].includes(el.dataset.page))action(()=>journeys.sync({detail:true}));}));root.querySelectorAll('[data-auth]').forEach(el=>el.addEventListener('click',()=>{state.auth=el.dataset.auth;state.error='';render();}));root.querySelectorAll('[data-collect]').forEach(el=>el.addEventListener('click',()=>{state.collectMode=el.dataset.collect;render();}));root.querySelectorAll('[data-key]').forEach(el=>el.addEventListener('click',()=>updateCollect(el.dataset.key)));root.querySelector('#collect-note')?.addEventListener('input',event=>state.collectNote=event.target.value);root.querySelector('#shop-selector')?.addEventListener('change',event=>{state.selection=event.target.value;state.collectAmount='';state.collectNote='';state.qr=null;state.latestPayment=null;state.knownPayments=null;render();});root.querySelectorAll('[data-fund]').forEach(el=>el.addEventListener('click',()=>{state.fundAmount=Number(el.dataset.fund);render();}));root.querySelectorAll('[data-receipt]').forEach(el=>el.addEventListener('click',()=>{state.receipt=currentActivity().find(r=>r.id===el.dataset.receipt);if(state.receipt)go('receipt');}));root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>onAction(el.dataset.action)));root.querySelector('[name=budgetCategoryId]')?.addEventListener('change',event=>{if(state.review){state.review.budgetCategoryId=event.target.value;render();}});bindForms();}
async function metadata(command,payload){const scope=ticket(),signature=JSON.stringify(payload),saved=state.metadataAttempts[command],attempt=saved?.signature===signature?saved:{signature,attemptId:crypto.randomUUID()};state.metadataAttempts[command]=attempt;try{const result=await client.command(command,{...payload,attemptId:attempt.attemptId});assertTicket(scope);delete state.metadataAttempts[command];return result;}catch(error){if(scopes.valid(scope,client?.user?.id||null)&&error.definitive&&error.attemptId===attempt.attemptId)delete state.metadataAttempts[command];throw error;}}
async function onAction(name){if(name==='refresh')return action(()=>refresh());if(name==='pay'||name==='fund'||name==='collect'||name==='activity'||name==='profile'||name==='scan'||name==='pending')return go(name);if(name==='myqr')return showMyQr();if(name==='static-qr')return showStaticQr();if(name==='switch-channel')return location.assign(channel==='merchant'?'/':'/merchant.html');if(name==='toggle-balance')return action(async()=>{const value=!state.hideBalance;await metadata('profile.update',{preferences:{hideBalance:value}});state.hideBalance=value;});if(name==='copy-reference')return copy(state.receipt?.reference||'','Receipt reference copied.');if(name==='copy-qr')return copy(state.qr?.raw||'','Lumo QR code copied.');if(name==='copy-static')return copy(encodeSharedQr({kind:'merchant',shopId:selected().shop.id}),'Shop QR code copied.');if(name==='done')return go('home');if(name==='new-amount'){state.collectAmount='';state.collectNote='';state.qr=null;return go('collect');}if(name==='add-business')return go('new-business');if(name==='add-shop')return go('new-shop');if(name==='sound')return action(async()=>{const value=!state.sound;await metadata('profile.update',{preferences:{sound:value}});state.sound=value;state.soundFault=false;if(value)speak('Payment alerts are on.');});if(name==='signout')return action(async()=>{stopCamera();await client.signOut();journeys.reset();state.account=null;state.activity=[];state.merchants=[];state.pending=null;state.knownPayments=null;state.page='home';});if(name==='recover')return action(recover);if(name==='refund')return go('refund');if(name==='close-shop')return action(async()=>{if(!window.confirm('Close this shop’s trading day? The collection counter resets. Business funds stay in the account.'))return;const scope=ticket();await metadata('merchant.close',{shopId:selected().shop.id});assertTicket(scope);await refresh();assertTicket(scope);toast('Trading day closed. Your business funds remain.');});if(name==='generate')return action(async()=>{const amount=parseMoney(state.collectAmount);if(!amount||state.pending)return;const scope=ticket(),{merchant,shop}=selected();const result=await metadata('request.create',{shopId:shop.id,amount,note:state.collectNote});assertTicket(scope);const request=result.request;if(!request||request.shopId!==shop.id||request.amount!==amount||!request.id||request.status!=='open'||!Number.isFinite(Date.parse(request.expiresAt))||Date.parse(request.expiresAt)<=Date.now())throw new Error('Invalid request');const intent={kind:'merchant',shopId:shop.id,requestId:request.id};state.qr={kind:'merchant',merchant,shop,request,intent,raw:encodeSharedQr(intent)};state.page='qr';});if(name==='qr-photo'){document.querySelector('#qr-file')?.click();return;}if(name==='camera'){stopCamera();cameraAbort=new AbortController();state.scanError='';const video=document.querySelector('#scan-video');document.querySelector('#scan-placeholder')?.setAttribute('hidden','');try{const localAbort=cameraAbort,scanScope=ticket();cameraStop=await mountScanner(video,raw=>{if(scopes.valid(scanScope,client?.user?.id||null)&&state.page==='scan')action(()=>readQr(raw));},error=>{if(!scopes.valid(scanScope,client?.user?.id||null)||state.page!=='scan')return;state.scanError=error.message||'The camera could not read this QR.';const el=document.querySelector('#scan-error');if(el)el.textContent=state.scanError;},{signal:localAbort.signal});}catch(error){state.scanError=error.message||'Camera access is unavailable. Try a QR photo.';const el=document.querySelector('#scan-error');if(el)el.textContent=state.scanError;}return;}}
function bindForms(){root.querySelector('#auth-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget,data=new FormData(form),register=state.auth==='register',handle=String(data.get('handle')||'').trim().replace(/^@/,'').toLowerCase(),password=String(data.get('password')||''),displayName=String(data.get('displayName')||'').trim(),pin=String(data.get('pin')||'');if(!/^[a-z][a-z0-9_]{2,29}$/.test(handle)||password.length<8||new TextEncoder().encode(password).length>72||register&&(!displayName||displayName.length>80||/[\p{Cc}<>]/u.test(displayName)||!/^[0-9]{4,6}$/.test(pin)||pin!==String(data.get('confirmPin')||'')||!data.get('consent'))){state.error=register?'Enter your name, a valid handle, a password of at least 8 characters and matching 4–6 digit PINs. Confirm that these are test funds.':'Enter your Lumo handle and password.';document.querySelector('#inline-error').textContent=state.error;return;}form.querySelectorAll('[type=password]').forEach(e=>e.value='');action(async()=>{const scope=ticket();const session=await authRequest(register?'register':'login',{handle,password,...(register?{displayName,pin}:{})});assertTicket(scope);const hadIncoming=!!sessionStorage.getItem('lumo.connected.incoming.v1');await signedIn(session);if(register&&!hadIncoming)state.page='welcome-connected';});});
  root.querySelector('#recipient-form')?.addEventListener('submit',event=>{event.preventDefault();const handle=String(new FormData(event.currentTarget).get('handle')||'').trim().toLowerCase();action(async()=>{const scope=ticket(),result=await client.lookupRecipient(handle);assertTicket(scope);if(result.recipient.id===client.user.id){toast('Choose another Lumo account.');return;}state.recipient=result.recipient;state.page='amount';});});
  root.querySelector('#amount-form')?.addEventListener('submit',event=>{event.preventDefault();const amount=parseMoney(String(new FormData(event.currentTarget).get('amount')||''));if(!amount||amount>state.account.balance){document.querySelector('#inline-error').textContent='Enter an amount within your available Everyday balance.';return;}state.review={kind:'transfer',recipient:{...state.recipient},amount};go('review');});
  root.querySelector('#merchant-amount-form')?.addEventListener('submit',event=>{event.preventDefault();try{const r=state.review;validateQuote(r.intent,r.quote);const amount=r.intent.requestId?r.quote.request.amount:parseMoney(String(new FormData(event.currentTarget).get('amount')||''));if(!amount||amount>state.account.balance){document.querySelector('#inline-error').textContent='Enter an amount within your available Everyday balance. Add test funds if needed.';return;}r.amount=amount;go('review');}catch(error){document.querySelector('#inline-error').textContent=error.message;}});
  root.querySelector('#approve-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),pin=String(data.get('pin')||''),budgetCategoryId=String(data.get('budgetCategoryId')||'');if(event.currentTarget.querySelector('[name=pin]'))event.currentTarget.querySelector('[name=pin]').value='';const original=state.review;original.budgetCategoryId=budgetCategoryId;if(original.kind!=='refund'&&journeys.pauseFor({command:original.kind==='merchant'?'payment.pay':'transfer',amount:original.amount,budgetCategoryId},()=>go('review')))return;if(!/^[0-9]{4,6}$/.test(pin)){document.querySelector('#inline-error').textContent='Enter your 4–6 digit payment PIN.';return;}const r=state.review;action(async()=>{const scope=ticket();let result;if(r.kind==='transfer')result=await client.transfer({recipientHandle:r.recipient.handle,amount:r.amount,pin,...(budgetCategoryId?{budgetCategoryId}:{})});else if(r.kind==='refund')result=await client.refundPayment({paymentId:r.payment.id,amount:r.amount,pin});else{validateQuote(r.intent,r.quote);result=await client.payMerchant({shopId:r.intent.shopId,...(r.intent.requestId?{requestId:r.intent.requestId}:{}),amount:r.amount,pin,...(budgetCategoryId?{budgetCategoryId}:{})});}assertTicket(scope);await completeMoney(result,r.kind==='refund'?'Refund confirmed.':'Payment complete.',scope);});});
  root.querySelector('#fund-form')?.addEventListener('submit',event=>{event.preventDefault();if(!new FormData(event.currentTarget).get('confirm')){document.querySelector('#inline-error').textContent='Confirm that these funds have no real monetary value.';return;}action(async()=>{const scope=ticket(),result=await client.fundTestWallet(state.fundAmount,{confirmSandbox:true});assertTicket(scope);await completeMoney(result,'Test funds added.',scope);});});
  root.querySelector('#retry-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),credentials=Object.fromEntries(['pin','partnerCode','oldPin','newPin'].filter(name=>data.has(name)).map(name=>[name,String(data.get(name)||'')]));event.currentTarget.querySelectorAll('[type=password]').forEach(el=>el.value='');action(async()=>{const scope=ticket(),result=await client.retryPending(credentials);assertTicket(scope);await completeMoney(result,result.receipt?.type==='refund'?'Refund confirmed.':'Request confirmed.',scope);});});
  root.querySelector('#merchant-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget),businessName=String(data.get('businessName')||'').trim(),shopName=String(data.get('shopName')||'').trim();if(!businessName||!shopName||businessName.length>100||shopName.length>100){document.querySelector('#inline-error').textContent='Enter a business name and shop name.';return;}action(async()=>{const scope=ticket(),result=await metadata('merchant.create',{businessName,shopName});assertTicket(scope);state.selection=result.shop?.id||null;state.knownPayments=null;state.page='collect';await refresh();});});
  root.querySelector('#shop-form')?.addEventListener('submit',event=>{event.preventDefault();const name=String(new FormData(event.currentTarget).get('name')||'').trim();if(!name||name.length>100){document.querySelector('#inline-error').textContent='Enter a shop name.';return;}action(async()=>{const scope=ticket(),result=await metadata('shop.create',{merchantId:selected().merchant.id,name});assertTicket(scope);state.selection=result.shop?.id||null;state.knownPayments=null;state.page='collect';await refresh();});});
  root.querySelector('#refund-form')?.addEventListener('submit',event=>{event.preventDefault();const amount=parseMoney(String(new FormData(event.currentTarget).get('amount')||'')),payment=state.receipt;if(!amount||amount>remainingRefund(payment,currentActivity())){document.querySelector('#inline-error').textContent='Enter an amount within the remaining original payment.';return;}state.review={kind:'refund',payment:{...payment},amount};go('review');});
  root.querySelector('#qr-paste-form')?.addEventListener('submit',event=>{event.preventDefault();const code=String(new FormData(event.currentTarget).get('code')||'');action(()=>readQr(code));});root.querySelector('#qr-file')?.addEventListener('change',event=>{const file=event.target.files?.[0];if(file)action(async()=>{const scope=ticket();let raw;try{raw=await decodeQrImage(file);assertTicket(scope);}catch(error){state.scanError=error.message;throw error;}await readQr(raw);});});
}

async function boot(){try{const response=await fetch('/runtime-config.json',{cache:'no-store',redirect:'error'});if(!response.ok)throw new Error('Missing runtime configuration');config=await response.json();if(config.sandbox!==true||config.supabaseUrl!=='https://iwutbrljiiodamtyoorg.supabase.co'||!String(config.publishableKey||'').startsWith('sb_publishable_'))throw new Error('Invalid runtime configuration');client=createLumoClient({url:config.supabaseUrl,publishableKey:config.publishableKey,pendingStorage:localStorage,onSessionChange:session=>{const nextOwner=session?.user?.id||null;if(nextOwner!==lastAuthOwner){lastAuthOwner=nextOwner;clearAccountView();}if(session)localStorage.setItem(SESSION_KEY,JSON.stringify(session));else localStorage.removeItem(SESSION_KEY);}});try{state.sound=localStorage.getItem('lumo.connected.sound.v1')==='true';state.hideBalance=localStorage.getItem('lumo.connected.hideBalance.v1')!=='false';}catch{}const incoming=new URL(location.href).searchParams.get('qr');if(incoming){try{parseSharedQr(incoming);sessionStorage.setItem('lumo.connected.incoming.v1',incoming);}catch{state.error='That Lumo QR could not be read. Ask for a fresh code.';}history.replaceState(null,'',location.pathname);}const cached=localStorage.getItem(SESSION_KEY);if(cached){try{await client.restoreSession(JSON.parse(cached));await refresh();}catch{state.error='Sign in again to open your shared account.';await client.signOut().catch(()=>{});}}booted=true;render();if(client.signedIn){const raw=sessionStorage.getItem('lumo.connected.incoming.v1');if(raw){sessionStorage.removeItem('lumo.connected.incoming.v1');await action(()=>readQr(raw));}}}catch{root.setAttribute('aria-busy','false');root.innerHTML=`<header class="topbar"><span class="wordmark">lumo</span></header><main class="empty-error"><h1>We couldn’t open Lumo.</h1><p>Please reload the page. Your saved account and payment reference stay on this device.</p><button class="button" id="reload">Try again</button></main>`;document.querySelector('#reload').onclick=()=>location.reload();}}
window.addEventListener('popstate',event=>{if(!client?.signedIn||state.busy)return;const next=event.state?.lumoPage||'home';replayingHistory=true;go(next==='review'&&!state.review||next==='connected-review'&&!journeys.ext.review||next==='pause'&&!journeys.ext.pause||next==='qr'&&!state.qr?'home':next);});window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera();else if(booted&&client?.signedIn&&!state.busy)refresh({quiet:true});});window.addEventListener('keydown',event=>{if(channel!=='merchant'||state.page!=='collect'||state.collectMode!=='amount'||state.busy||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||''))return;const key=event.key==='Backspace'?'back':event.key==='Escape'?'clear':event.key;if(/^[0-9.]$/.test(key)||['back','clear'].includes(key)){event.preventDefault();updateCollect(key);}});window.addEventListener('storage',async event=>{
  if(event.key!==SESSION_KEY||!booted)return;
  let session;try{session=event.newValue?JSON.parse(event.newValue):null;}catch{return;}
  if(session?.user?.id===client.user?.id&&session)return;
  const serial=++storageSerial;authChanging=true;clearAccountView();const scope=ticket();render();
  try{if(session)await client.restoreSession(session);else await client.signOut();}
  catch{if(serial===storageSerial&&scopes.valid(scope,client?.user?.id||null))await client.signOut().catch(()=>{});}
  finally{if(serial===storageSerial){authChanging=false;if(client.signedIn)await refresh();render();}}
});setInterval(()=>{if(!booted||!client?.signedIn||state.busy||document.hidden||Date.now()-lastPoll<5000)return;lastPoll=Date.now();refresh({quiet:true});},1500);
boot();
